/**
 * @param {number} times
 * @return {string}
 */
String.prototype.replicate = function(times) {
    return new Array(times).fill(this).join('');
};

declare global {
    interface String {
        replicate(times: number): string;
    }
}

String.prototype.replicate = function(times: number): string {
    return new Array(times).fill(this).join('');
};
